<?php
$pageTitle='User accounts';
require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    if($action==='create'){
        $name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'worker');
        if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('error','Enter a name and valid email address.');redirect('index.php?page=users');}
        if(strlen($password)<10){flash('error','Password must contain at least 10 characters.');redirect('index.php?page=users');}
        if(!in_array($role,['admin','project_manager','site_supervisor','worker'],true))$role='worker';
        try{$st=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,?)');$st->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);flash('success','User account created. Share the temporary password securely.');}catch(PDOException $ex){flash('error','Could not create account. That email address may already exist.');}redirect('index.php?page=users');
    }
    if($action==='change_role'){
        $id=(int)($_POST['id']??0);$role=(string)($_POST['role']??'worker');if($id===(int)user()['id']){flash('error','You cannot change your own role while signed in.');redirect('index.php?page=users');}if(!in_array($role,['admin','project_manager','site_supervisor','worker'],true))$role='worker';$st=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$st->execute([$role,$id]);flash('success','User role updated.');redirect('index.php?page=users');
    }
    if($action==='reset_password'){
        $id=(int)($_POST['id']??0);$password=(string)($_POST['new_password']??'');if(strlen($password)<10){flash('error','New password must contain at least 10 characters.');redirect('index.php?page=users');}$st=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$st->execute([password_hash($password,PASSWORD_DEFAULT),$id]);flash('success','Password reset. Deliver the new password to the user through a secure channel.');redirect('index.php?page=users');
    }
}
$users=$pdo->query("SELECT u.id,u.full_name,u.email,u.role,u.created_at,(SELECT COUNT(*) FROM tasks t WHERE t.assigned_to=u.id AND t.status<>'completed') AS open_tasks FROM users u ORDER BY CASE u.role WHEN 'admin' THEN 0 WHEN 'project_manager' THEN 1 WHEN 'site_supervisor' THEN 2 ELSE 3 END,u.full_name")->fetchAll();
require __DIR__ . '/../inc/header.php';
?>
<div class="page-toolbar"><p class="muted">Create accounts and grant permissions. Give each person only the access needed for their role.</p><span class="toolbar-count"><strong><?= count($users) ?></strong> accounts</span></div>
<section class="panel form-panel"><div class="panel-heading"><div><h3>Create a user account</h3><p>A password must be at least 10 characters long.</p></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label>Full name *<input name="full_name" maxlength="120" required></label><label>Email address *<input type="email" name="email" maxlength="190" required></label><label>Temporary password *<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><label>Role<select name="role"><option value="worker">Worker</option><option value="site_supervisor">Site Supervisor</option><option value="project_manager">Project Manager</option><option value="admin">Administrator</option></select></label><div class="form-actions span-2"><button class="btn btn-primary">Create account</button></div></form></section>
<section class="panel"><div class="panel-heading"><div><h3>Registered users</h3><p>Roles determine access to project features.</p></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Open assigned tasks</th><th>Account created</th><th>Update role</th><th>Reset password</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['full_name']) ?></strong><small class="cell-sub"><?= e($u['email']) ?></small></td><td><span class="role-pill role-<?= e($u['role']) ?>"><?= e(role_label($u['role'])) ?></span></td><td><?= (int)$u['open_tasks'] ?></td><td><?= e(date_label(substr($u['created_at'],0,10))) ?></td><td><?php if((int)$u['id']===(int)user()['id']): ?><span class="muted small">Current account</span><?php else: ?><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="change_role"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><select name="role" aria-label="Role for <?= e($u['full_name']) ?>"><?php foreach(['admin','project_manager','site_supervisor','worker'] as $role): ?><option value="<?= e($role) ?>" <?= $u['role']===$role?'selected':'' ?>><?= e(role_label($role)) ?></option><?php endforeach; ?></select><button class="action-link">Save</button></form><?php endif; ?></td><td><?php if((int)$u['id']!==(int)user()['id']): ?><form method="post" class="inline-form" onsubmit="return confirm('Reset this user password?');"><?= csrf_field() ?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="password" name="new_password" minlength="10" placeholder="New password" required aria-label="New password"><button class="action-link">Reset</button></form><?php else: ?><span class="muted small">Use account security options</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="alert alert-info">For a real deployment, require password changes after administrator resets and enable HTTPS. This student prototype stores passwords with PHP's password hashing functions.</div>
<?php require __DIR__ . '/../inc/footer.php'; ?>
